package com.captrojo.crwg.compat;

import com.captrojo.crwg.world.gen.data.GenArrays;

import net.minecraft.block.Block;
import net.minecraft.world.World;
import net.minecraft.world.biome.BiomeGenBase;
import net.minecraft.world.chunk.Chunk;

public interface ICRWGFuncs
{
	/**
	 * Creates a chunk from arrays generated by ChunkProviderCRWG.
	 * 
	 * Sea level is at Y posision U+127 in the ablock and ameta arrays, where U is the value
	 * returned by getExtraUndergroundSize.
	 * 
	 * The `ablock` and `ameta` arrays are indexed by [X | (Z << 4) | (Y << 8)].
	 * The `abiome` and `abiomeid` arrays are indexed by [X | (Z << 4)].
	 */
	Chunk createChunkFromArrays(
		World world,
		int chunk_x,
		int chunk_z,
		Block[] ablock,
		short[] ameta,
		BiomeGenBase[] abiome,
		short[] abiomeid,
		GenArrays arrays
	);

	/**
	 * Check if a coordinate is within the world border (within 30 million from (0, 0), and
	 * not outside min/max height limits)
	 */
	boolean isWithinWorld(int x, int y, int z);

	boolean isWithinWorld(int x, int z);

	/**
	 * Get the bottom height limit of the world. Used for things like world gen checks.
	 * Also used to calculate indices into `ablock` and `ameta` arrays. This is an actual
	 * Y coordinate.
	 */
	int getMinHeight();

	/**
	 * Get the top height limit of the world. Used for things like world gen checks. This is
	 * an actual Y coordinate.
	 */
	int getMaxHeight();

	/**
	 * Get actual sea level of the world. This is an actual Y coordinate, NOT an index into
	 * the `ablock` or `ameta` arrays.
	 * 
	 * This should be the height of the last water block.
	 */
	int getSeaLevel();

	/**
	 * Get the size of an extra underground portion below the minimum Y of terrain generation.
	 * 
	 * Remember to update the parameters for ore generation and the values returned by the
	 * getMinCaveHeight and getMaxCaveHeight functions.
	 */
	int getExtraUndergroundSize();

	/**
	 * Get whether vanilla-style caves should generate or not
	 */
	boolean shouldGenerateCaves();

	/**
	 * Get the minimum height of caves. This is a Y index of the `ablock` and `ameta` arrays,
	 * NOT an actual Y coordinate.
	 */
	int getMinCaveHeight();

	/**
	 * Get the maximum height of caves. This is a Y index of the `ablock` and `ameta` arrays,
	 * NOT an actual Y coordinate.
	 */
	int getMaxCaveHeight();

	/**
	 * Get whether vanilla-style ravines should generate or not
	 */
	boolean shouldGenerateRavines();

	/**
	 * The ravine height formula is as follows:
	 * Y = (this.rand.nextInt(this.rand.nextInt(H1) + H2) + H3)
	 * 
	 * Vanilla world gen uses the values 40, 8, and 20, respectively.
	 * These are Y indicies of the `ablock` and `ameta` arrays, NOT actual Y coordinates.
	 */
	int getRavineHeight1();

	int getRavineHeight2();

	int getRavineHeight3();
}
